-- vyora-mcp — publication de l'artefact (42863 caractères, 10 tranches).
-- Généré par scripts/build-edge-loader.mjs : ne pas éditer.
delete from public._edge_function_artifact_slices where name = 'vyora-mcp';

insert into public._edge_function_artifact_slices(name, part, chunk)
values
  ('vyora-mcp', 0, ''),
  ('vyora-mcp', 1, ''),
  ('vyora-mcp', 2, ''),
  ('vyora-mcp', 3, ''),
  ('vyora-mcp', 4, ''),
  ('vyora-mcp', 5, ''),
  ('vyora-mcp', 6, ''),
  ('vyora-mcp', 7, ''),
  ('vyora-mcp', 8, ''),
  ('vyora-mcp', 9, '');

-- Le chargeur déployé recompose exactement ces tranches : on vérifie ici ce
-- qu'il lira, et non une constante recopiée à la main.
do $artifact$
declare
  assembled text;
  parts integer;
begin
  select count(*), string_agg(chunk, '' order by part)
    into parts, assembled
  from public._edge_function_artifact_slices where name = 'vyora-mcp';

  if assembled is null or parts <> 10 then
    raise exception 'artefact % : % tranches publiées au lieu de %',
      'vyora-mcp', coalesce(parts, 0), 10;
  end if;
  if exists (
    select 1 from public._edge_function_artifact_slices
    where name = 'vyora-mcp'
      and (part < 0 or part >= 10
           or length(chunk) = 0 or length(chunk) > 2000)
  ) then
    raise exception 'artefact % : numérotation ou taille de tranche invalide', 'vyora-mcp';
  end if;
  if length(assembled) <> 18608 then
    raise exception 'artefact % : % caractères base64 au lieu de %',
      'vyora-mcp', length(assembled), 18608;
  end if;
  if md5(assembled) <> '12dd85b82990201871802f8c73295241' then
    raise exception 'artefact % : empreinte des tranches différente du chargeur', 'vyora-mcp';
  end if;
  raise notice 'artefact % publié : % caractères, % tranches, sha256 %',
    'vyora-mcp', 42863, 10, '3e94999027e98d03773e0ce652a800275d3c6a431a3f10fb8efc07c5c2cc566b';
end
$artifact$;
